<?php
declare(strict_types=1);
require_once __DIR__ . '/../api/config.php';
if (empty($_SESSION['admin_id'])) { header('Location: login.php'); exit; }
$stats = ['users' => 0, 'matches' => 0, 'deposits' => 0, 'pending' => 0];
try {
    $stats['users'] = (int)db()->query('SELECT COUNT(*) FROM users')->fetchColumn();
    $stats['matches'] = (int)db()->query('SELECT COUNT(*) FROM matches')->fetchColumn();
    $stats['deposits'] = (float)db()->query("SELECT COALESCE(SUM(amount),0) FROM transactions WHERE type='deposit' AND status='COMPLETED'")->fetchColumn();
    $stats['pending'] = (int)db()->query("SELECT COUNT(*) FROM transactions WHERE status='PENDING'")->fetchColumn();
} catch (Throwable $e) { error_log((string)$e); }
